import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  serverExternalPackages: [
    "@modelcontextprotocol/sdk",
    "mcp-handler",
    "@azure/identity",
    "@azure/keyvault-certificates",
    "@azure/keyvault-keys",
    "node-forge",
  ],
  webpack: (config) => {
    // Support NodeNext-style ".js" imports that resolve to ".ts" sources.
    config.resolve = config.resolve ?? {};
    config.resolve.extensionAlias = {
      ".js": [".ts", ".tsx", ".js"],
    };
    return config;
  },
};

export default nextConfig;

import { createHash } from "node:crypto";
import { CertificateClient } from "@azure/keyvault-certificates";
import { CryptographyClient } from "@azure/keyvault-keys";
import { DefaultAzureCredential, ClientSecretCredential } from "@azure/identity";

function env(key: string): string {
  return (process.env[key] ?? "").trim();
}

export type AzureKeyVaultConfig = {
  vaultUrl: string;
};

export function isAzureKeyVaultConfigured(): boolean {
  return Boolean(env("AZURE_KEY_VAULT_URL"));
}

export function resolveAzureKeyVaultConfig(): AzureKeyVaultConfig | null {
  const vaultUrl = env("AZURE_KEY_VAULT_URL");
  if (!vaultUrl) return null;
  return { vaultUrl };
}

export function getAzureCredential() {
  const tenantId = env("AZURE_TENANT_ID");
  const clientId = env("AZURE_CLIENT_ID");
  const clientSecret = env("AZURE_CLIENT_SECRET");
  if (tenantId && clientId && clientSecret) {
    return new ClientSecretCredential(tenantId, clientId, clientSecret);
  }
  return new DefaultAzureCredential();
}

export async function keyVaultResolveKeyId(
  certificateName: string,
  _teamId?: string
): Promise<string> {
  const config = resolveAzureKeyVaultConfig();
  if (!config?.vaultUrl) {
    throw new Error("Azure Key Vault ist nicht konfiguriert (AZURE_KEY_VAULT_URL).");
  }
  const name = certificateName.trim();
  if (!name) throw new Error("Zertifikatsname fehlt.");

  const certClient = new CertificateClient(config.vaultUrl, getAzureCredential());
  const cert = await certClient.getCertificate(name);
  if (!cert.keyId) {
    throw new Error("Schlüssel-ID nicht gefunden — Zertifikat evtl. noch nicht gemerged.");
  }
  return cert.keyId;
}

export async function keyVaultSignCbConnectPayload(
  keyId: string,
  signingInput: string,
  _teamId?: string
): Promise<string> {
  if (!isAzureKeyVaultConfigured()) {
    throw new Error("Azure Key Vault ist nicht konfiguriert.");
  }
  const digest = createHash("sha256").update(signingInput, "utf8").digest();
  const crypto = new CryptographyClient(keyId, getAzureCredential());
  const result = await crypto.sign("RS256", digest);
  return Buffer.from(result.result).toString("base64");
}

export async function keyVaultSignCbConnectPayloadForCertificate(
  certificateName: string,
  signingInput: string,
  teamId?: string
): Promise<{ signatureBase64: string; keyId: string }> {
  const keyId = await keyVaultResolveKeyId(certificateName, teamId);
  const signatureBase64 = await keyVaultSignCbConnectPayload(
    keyId,
    signingInput,
    teamId
  );
  return { signatureBase64, keyId };
}

/**
 * Strukturierte CAMT.053-Ansicht für die Kontoauszüge-Analyse.
 */

export type Camt053GroupHeader = {
  messageId: string | null;
  creationDateTime: string | null;
  pageNumber: string | null;
  lastPageIndicator: string | null;
};

export type Camt053BalanceLine = {
  typeCode: string | null;
  amount: string | null;
  currency: string | null;
  creditDebit: string | null;
  date: string | null;
};

export type Camt053StatementInfo = {
  statementId: string | null;
  creationDateTime: string | null;
  accountId: string | null;
  accountOwner: string | null;
  servicerName: string | null;
  periodFrom: string | null;
  periodTo: string | null;
  balances: Camt053BalanceLine[];
};

export type Camt053EntryLine = {
  index: number;
  amount: string | null;
  currency: string | null;
  creditDebit: string | null;
  status: string | null;
  bookingDate: string | null;
  valueDate: string | null;
  accountServicerRef: string | null;
  bankTransactionCode: string | null;
  counterparty: string | null;
  endToEndId: string | null;
  remittanceInfo: string | null;
};

export type Camt053Analysis = {
  groupHeader: Camt053GroupHeader;
  statements: Array<{
    info: Camt053StatementInfo;
    entries: Camt053EntryLine[];
  }>;
};

function asRecord(v: unknown): Record<string, unknown> | undefined {
  if (v && typeof v === "object" && !Array.isArray(v)) {
    return v as Record<string, unknown>;
  }
  return undefined;
}

function asArray<T>(v: T | T[] | undefined): T[] {
  if (v === undefined) return [];
  return Array.isArray(v) ? v : [v];
}

function pickString(v: unknown): string | null {
  if (typeof v === "string" && v.trim()) return v.trim();
  if (typeof v === "number" && !Number.isNaN(v)) return String(v);
  return null;
}

function extractAttributes(o: Record<string, unknown>): Record<string, string> | undefined {
  const attrs: Record<string, string> = {};
  for (const [key, val] of Object.entries(o)) {
    if (!key.startsWith("@_")) continue;
    const name = key.slice(2);
    const s = pickString(val);
    if (s != null) attrs[name] = s;
  }
  return Object.keys(attrs).length > 0 ? attrs : undefined;
}

function amountFromNode(amt: unknown): { amount: string | null; currency: string | null } {
  const rec = asRecord(amt);
  if (!rec) {
    const s = pickString(amt);
    return { amount: s, currency: null };
  }
  const attrs = extractAttributes(rec);
  const text = pickString(rec["#text"]) ?? pickString(rec);
  return { amount: text, currency: attrs?.Ccy ?? null };
}

function accountIdFromAcct(acct: Record<string, unknown> | undefined): string | null {
  if (!acct) return null;
  const id = asRecord(acct.Id);
  if (!id) return null;
  const iban = pickString(id.IBAN);
  if (iban) return iban;
  const othr = asRecord(id.Othr);
  return pickString(othr?.Id);
}

function balanceTypeCode(bal: Record<string, unknown>): string | null {
  const tp = asRecord(bal.Tp);
  const cdOrPrtry = asRecord(tp?.CdOrPrtry);
  return pickString(cdOrPrtry?.Cd) ?? pickString(cdOrPrtry?.Prtry);
}

function balanceDate(bal: Record<string, unknown>): string | null {
  const dt = asRecord(bal.Dt);
  return pickString(dt?.Dt) ?? pickString(dt?.DtTm);
}

function bankTxCode(ntry: Record<string, unknown>): string | null {
  const bk = asRecord(ntry.BkTxCd);
  const domn = asRecord(bk?.Domn);
  const cd = pickString(domn?.Cd);
  const fmly = asRecord(domn?.Fmly);
  const fmlyCd = pickString(fmly?.Cd);
  const sub = pickString(fmly?.SubFmlyCd);
  const parts = [cd, fmlyCd, sub].filter(Boolean);
  return parts.length > 0 ? parts.join(" / ") : null;
}

function entryCounterparty(ntry: Record<string, unknown>): string | null {
  for (const dtl of asArray(ntry.NtryDtls)) {
    const dtlRec = asRecord(dtl);
    for (const tx of asArray(dtlRec?.TxDtls)) {
      const txRec = asRecord(tx);
      const parties = asRecord(txRec?.RltdPties);
      const dbtr = pickString(asRecord(parties?.Dbtr)?.Nm);
      if (dbtr) return dbtr;
      const cdtr = pickString(asRecord(parties?.Cdtr)?.Nm);
      if (cdtr) return cdtr;
    }
  }
  return null;
}

function entryEndToEndId(ntry: Record<string, unknown>): string | null {
  for (const dtl of asArray(ntry.NtryDtls)) {
    const dtlRec = asRecord(dtl);
    for (const tx of asArray(dtlRec?.TxDtls)) {
      const txRec = asRecord(tx);
      const refs = asRecord(txRec?.Refs);
      const e2e = pickString(refs?.EndToEndId);
      if (e2e) return e2e;
    }
  }
  return null;
}

function entryRemittance(ntry: Record<string, unknown>): string | null {
  for (const dtl of asArray(ntry.NtryDtls)) {
    const dtlRec = asRecord(dtl);
    for (const tx of asArray(dtlRec?.TxDtls)) {
      const txRec = asRecord(tx);
      const rmt = asRecord(txRec?.RmtInf);
      const ustrd = pickString(rmt?.Ustrd);
      if (ustrd) return ustrd;
    }
  }
  return null;
}

function parseGroupHeader(bk: Record<string, unknown>): Camt053GroupHeader {
  const grp = asRecord(bk.GrpHdr);
  const pgntn = asRecord(grp?.MsgPgntn);
  return {
    messageId: pickString(grp?.MsgId),
    creationDateTime: pickString(grp?.CreDtTm),
    pageNumber: pickString(pgntn?.PgNb),
    lastPageIndicator: pickString(pgntn?.LastPgInd),
  };
}

function parseStatementInfo(stmt: Record<string, unknown>): Camt053StatementInfo {
  const acct = asRecord(stmt.Acct);
  const frTo = asRecord(stmt.FrToDt);
  const svcr = asRecord(asRecord(acct?.Svcr)?.FinInstnId);

  const balances: Camt053BalanceLine[] = [];
  for (const bal of asArray(stmt.Bal)) {
    const balRec = asRecord(bal);
    if (!balRec) continue;
    const { amount, currency } = amountFromNode(balRec.Amt);
    balances.push({
      typeCode: balanceTypeCode(balRec),
      amount,
      currency,
      creditDebit: pickString(balRec.CdtDbtInd),
      date: balanceDate(balRec),
    });
  }

  return {
    statementId: pickString(stmt.Id),
    creationDateTime: pickString(stmt.CreDtTm),
    accountId: accountIdFromAcct(acct),
    accountOwner: pickString(asRecord(acct?.Ownr)?.Nm),
    servicerName: pickString(svcr?.Nm),
    periodFrom: pickString(frTo?.FrDtTm) ?? pickString(asRecord(frTo?.FrDtTm)?.Dt),
    periodTo: pickString(frTo?.ToDtTm) ?? pickString(asRecord(frTo?.ToDtTm)?.Dt),
    balances,
  };
}

function parseEntryLine(ntry: Record<string, unknown>, index: number): Camt053EntryLine {
  const { amount, currency } = amountFromNode(ntry.Amt);
  const bookg = asRecord(ntry.BookgDt);
  const valDt = asRecord(ntry.ValDt);

  return {
    index,
    amount,
    currency,
    creditDebit: pickString(ntry.CdtDbtInd),
    status: pickString(ntry.Sts),
    bookingDate: pickString(bookg?.DtTm) ?? pickString(bookg?.Dt),
    valueDate: pickString(valDt?.Dt) ?? pickString(valDt?.DtTm),
    accountServicerRef: pickString(ntry.AcctSvcrRef),
    bankTransactionCode: bankTxCode(ntry),
    counterparty: entryCounterparty(ntry),
    endToEndId: entryEndToEndId(ntry),
    remittanceInfo: entryRemittance(ntry),
  };
}

export function buildCamt053Analysis(
  parsedTree: Record<string, unknown>
): Camt053Analysis | null {
  const doc = asRecord(parsedTree.Document) ?? parsedTree;
  const bk = asRecord(doc.BkToCstmrStmt);
  if (!bk) return null;

  const groupHeader = parseGroupHeader(bk);
  const rawStmts = bk.Stmt;
  const stmts = asArray(rawStmts)
    .map((s) => asRecord(s))
    .filter((s): s is Record<string, unknown> => !!s);

  const statements = stmts.map((stmt) => {
    const entries = asArray(stmt.Ntry)
      .map((n) => asRecord(n))
      .filter((n): n is Record<string, unknown> => !!n)
      .map((n, i) => parseEntryLine(n, i + 1));

    return {
      info: parseStatementInfo(stmt),
      entries,
    };
  });

  return { groupHeader, statements };
}

export function formatCamtAmount(
  amount: string | null,
  currency: string | null,
  creditDebit: string | null
): string {
  if (!amount) return "—";
  const num = Number(amount.replace(",", "."));
  const formatted = Number.isFinite(num)
    ? num.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : amount;
  const sign = creditDebit === "DBIT" ? "−" : creditDebit === "CRDT" ? "+" : "";
  const ccy = currency ? ` ${currency}` : "";
  return `${sign}${formatted}${ccy}`.trim();
}

export function formatCamtDateTime(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString("de-DE", { dateStyle: "medium", timeStyle: "short" });
}

import { XMLParser } from "fast-xml-parser";

import { CAMT053_SCHEMA } from "./camt053-shared.js";
import type {
  Camt053FieldRow,
  Camt053Summary,
} from "./camt053-shared.js";
import { isCbConnectCamtStatementXml } from "./cb-connect-statements-parse.js";

const camt053Parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: "@_",
  trimValues: true,
  removeNSPrefix: true,
  parseTagValue: false,
  /** Text + Attribute: { "#text": "…", "@_Ccy": "EUR" } */
  textNodeName: "#text",
});

export type Camt053ParseResult = {
  schemaVersion: typeof CAMT053_SCHEMA;
  messageId: string | null;
  summary: Camt053Summary;
  fields: Camt053FieldRow[];
  parsedTree: Record<string, unknown>;
};

function asRecord(v: unknown): Record<string, unknown> | undefined {
  if (v && typeof v === "object" && !Array.isArray(v)) {
    return v as Record<string, unknown>;
  }
  return undefined;
}

function asArray<T>(v: T | T[] | undefined): T[] {
  if (v === undefined) return [];
  return Array.isArray(v) ? v : [v];
}

function statementsFromBk(
  bk: Record<string, unknown> | undefined
): Record<string, unknown>[] {
  const raw = bk?.Stmt;
  if (raw == null) return [];
  if (Array.isArray(raw)) {
    return raw
      .map((s) => asRecord(s))
      .filter((s): s is Record<string, unknown> => !!s);
  }
  const one = asRecord(raw);
  return one ? [one] : [];
}

function pickString(v: unknown): string | null {
  if (typeof v === "string" && v.trim()) return v.trim();
  if (typeof v === "number" && !Number.isNaN(v)) return String(v);
  return null;
}

function extractAttributes(o: Record<string, unknown>): Record<string, string> | undefined {
  const attrs: Record<string, string> = {};
  for (const [key, val] of Object.entries(o)) {
    if (!key.startsWith("@_")) continue;
    const name = key.slice(2);
    const s = pickString(val);
    if (s != null) attrs[name] = s;
  }
  return Object.keys(attrs).length > 0 ? attrs : undefined;
}

function scalarToString(v: unknown): string | null {
  if (v === null || v === undefined) return null;
  if (typeof v === "boolean") return v ? "true" : "false";
  return pickString(v);
}

/**
 * Flacht den geparsten CAMT-Baum zu Feldzeilen (alle XSD-Elemente/Attribute im XML).
 */
export function flattenCamt053Tree(
  node: unknown,
  path = "",
  out: Camt053FieldRow[] = []
): Camt053FieldRow[] {
  if (node === null || node === undefined) return out;

  if (typeof node === "string" || typeof node === "number" || typeof node === "boolean") {
    const value = scalarToString(node);
    if (value != null && path) {
      out.push({ path, value });
    }
    return out;
  }

  if (Array.isArray(node)) {
    node.forEach((item, index) => {
      const next = path ? `${path}[${index}]` : `[${index}]`;
      flattenCamt053Tree(item, next, out);
    });
    return out;
  }

  if (typeof node !== "object") return out;

  const o = node as Record<string, unknown>;
  const attrs = extractAttributes(o);
  const text = scalarToString(o["#text"]);

  if (text != null && path) {
    out.push({
      path,
      value: text,
      ...(attrs ? { attributes: attrs } : {}),
    });
    return out;
  }

  for (const [key, val] of Object.entries(o)) {
    if (key === "#text" || key.startsWith("@_")) continue;
    const nextPath = path ? `${path}.${key}` : key;
    flattenCamt053Tree(val, nextPath, out);
  }

  return out;
}

function accountIdFromAcct(acct: Record<string, unknown> | undefined): string | null {
  if (!acct) return null;
  const id = asRecord(acct.Id);
  if (!id) return null;
  const iban = pickString(id.IBAN);
  if (iban) return iban;
  const othr = asRecord(id.Othr);
  return pickString(othr?.Id);
}

function amountCurrency(ntry: Record<string, unknown>): string | null {
  const amt = asRecord(ntry.Amt);
  if (!amt) return null;
  const attrs = extractAttributes(amt);
  return attrs?.Ccy ?? null;
}

function buildSummary(root: Record<string, unknown>): Camt053Summary {
  const doc = asRecord(root.Document) ?? root;
  const bk = asRecord(doc.BkToCstmrStmt);
  const grp = asRecord(bk?.GrpHdr);
  const stmts = statementsFromBk(bk);

  const accountIdentifiers: string[] = [];
  const currencies = new Set<string>();
  let entryCount = 0;
  let balanceCount = 0;
  let periodFrom: string | null = null;
  let periodTo: string | null = null;

  for (const stmt of stmts) {
    if (!stmt) continue;
    const acctId = accountIdFromAcct(asRecord(stmt.Acct));
    if (acctId && !accountIdentifiers.includes(acctId)) {
      accountIdentifiers.push(acctId);
    }

    const frTo = asRecord(stmt.FrToDt);
    if (frTo) {
      periodFrom = pickString(frTo.FrDtTm) ?? periodFrom;
      periodTo = pickString(frTo.ToDtTm) ?? periodTo;
    }

    for (const bal of asArray(stmt.Bal)) {
      balanceCount += 1;
      const balRec = asRecord(bal);
      const amt = asRecord(balRec?.Amt);
      const ccy = amt ? extractAttributes(amt)?.Ccy : null;
      if (ccy) currencies.add(ccy);
    }

    for (const ntry of asArray(stmt.Ntry)) {
      entryCount += 1;
      const ntryRec = asRecord(ntry);
      const ccy = amountCurrency(ntryRec ?? {});
      if (ccy) currencies.add(ccy);
    }
  }

  return {
    messageId: pickString(grp?.MsgId),
    creationDateTime: pickString(grp?.CreDtTm),
    statementCount: stmts.length,
    entryCount,
    balanceCount,
    accountIdentifiers,
    currencies: [...currencies],
    periodFrom,
    periodTo,
  };
}

export function parseCamt053Xml(xml: string): Camt053ParseResult {
  const trimmed = xml.trim();
  if (!trimmed) {
    throw new Error("XML ist leer.");
  }
  if (!isCbConnectCamtStatementXml(trimmed)) {
    throw new Error(
      "Kein gültiges CAMT.053-Kontoauszugs-XML (Document / BkToCstmrStmt erwartet)."
    );
  }

  let parsed: Record<string, unknown>;
  try {
    parsed = camt053Parser.parse(trimmed) as Record<string, unknown>;
  } catch {
    throw new Error("XML konnte nicht geparst werden.");
  }

  const doc = asRecord(parsed.Document);
  if (!doc?.BkToCstmrStmt) {
    throw new Error("Document.BkToCstmrStmt fehlt im XML.");
  }

  const fields = flattenCamt053Tree(parsed);
  const summary = buildSummary(parsed);
  const grp = asRecord(asRecord(doc.BkToCstmrStmt)?.GrpHdr);

  return {
    schemaVersion: CAMT053_SCHEMA,
    messageId: summary.messageId ?? pickString(grp?.MsgId),
    summary,
    fields,
    parsedTree: parsed,
  };
}

/**
 * CAMT.053.001.02 — Bank-to-Customer Statement (ISO 20022).
 * Persistierte Felder entsprechen den im XML vorkommenden XSD-Elementen.
 */

export const CAMT053_SCHEMA = "camt.053.001.02" as const;

export type Camt053ImportSource =
  | "config-import"
  | "api-load"
  | "statements-ui";

export type Camt053FieldRow = {
  /** XPath-ähnlicher Pfad, z. B. BkToCstmrStmt.Stmt[0].Ntry[1].Amt */
  path: string;
  value: string;
  /** XML-Attribute am Element (z. B. Ccy auf Amt). */
  attributes?: Record<string, string>;
};

export type Camt053Summary = {
  messageId: string | null;
  creationDateTime: string | null;
  statementCount: number;
  entryCount: number;
  balanceCount: number;
  accountIdentifiers: string[];
  currencies: string[];
  periodFrom: string | null;
  periodTo: string | null;
};

export type Camt053StoredDocument = {
  id: string;
  teamId: string;
  schemaVersion: typeof CAMT053_SCHEMA;
  source: Camt053ImportSource;
  sourceRequestId: string | null;
  importedAt: number;
  messageId: string | null;
  summary: Camt053Summary;
  /** Alle im XML vorkommenden Blattwerte (XSD-Feldpfade). */
  fields: Camt053FieldRow[];
  /** Vollständiger geparster Baum (Namespace-stripped). */
  parsedTree: Record<string, unknown>;
  rawXml: string;
};

export type Camt053DocumentsPublic = {
  documents: Camt053StoredDocument[];
  updatedAt: number | null;
};

export type Camt053ImportResult =
  | { ok: true; document: Camt053StoredDocument }
  | { ok: false; error: string };

/** Öffentliche Konto-ID in der Kontenübersicht: `cb-connect:{linkedAccountUuid}` */

export const CB_CONNECT_ACCOUNT_ID_PREFIX = "cb-connect:";

/** Statement-Konto-ID in der Kontoauszüge-App: `cb-connect-stmt:{linkedAccountUuid}` */
export const CB_CONNECT_STMT_ACCOUNT_ID_PREFIX = "cb-connect-stmt:";

export function isCbConnectBankingAccountId(accountId: string): boolean {
  const raw = accountId?.trim() ?? "";
  if (!raw) return false;
  try {
