export type Fx4CashInitiationDocument = {
  customerCreditTransferInitiation: {
    groupHeader: {
      messageIdentification: string;
      creationDateTime: string;
      numberOfTransactions: number;
      controlSum: number;
      initiatingParty: {
        name: string;
        identification: {
          organisationIdentification: {
            anyBIC: string;
          };
        };
      };
    };
    paymentInformation: Array<{
      paymentInformationIdentification: string;
      paymentMethod: string;
      numberOfTransactions: number;
      batchBooking: boolean;
      controlSum: number;
      paymentTypeInformation: {
        serviceLevel: Array<{ code: string; proprietary: string }>;
      };
      requestedExecutionDate: { date: string };
      debtor: {
        name: string;
        postalAddress: {
          addressType: { code: string };
          department?: string;
          subDepartment?: string;
          streetName?: string;
          buildingNumber?: string;
          postCode?: string;
          townName?: string;
          countrySubDivision?: string;
          country: string;
          addressLine?: string[];
        };
      };
      debtorAccount: {
        identification: { other: { id: string } };
        currency: string;
      };
      debtorAgent: {
        financialInstitutionIdentification: {
          BICFI: string;
          name: string;
          postalAddress: { country: string; addressLine?: string[] };
        };
      };
      creditTransferTransactionInformation: Array<{
        paymentIdentification: {
          endToEndIdentification: string;
          instructionIdentification: string;
        };
        amount: {
          instructedAmount: { currency: string; amount: number };
        };
        creditor: {
          name: string;
          postalAddress: {
            addressType?: { code: string };
            department?: string;
            subDepartment?: string;
            streetName?: string;
            buildingNumber?: string;
            postCode?: string;
            townName?: string;
            countrySubDivision?: string;
            country: string;
            addressLine?: string[];
          };
          countryOfResidence?: string;
          contactDetails?: {
            name: string;
            emailAddress: string;
          };
        };
        creditorAccount: {
          identification:
            | { iban: string }
            | { other: { id: string } };
          currency: string;
        };
        creditorAgent: {
          financialInstitutionIdentification: {
            BICFI: string;
            name: string;
            postalAddress: { country: string; addressLine?: string[] };
          };
